import java.time.*;import java.util.*;
public class SubscriptionHarness{static int p=0;static List<String> f=new ArrayList<>();enum C{WEEKLY,MONTHLY,QUARTERLY,YEARLY}record S(String n,long a,C c,LocalDate next,boolean rem,boolean active){}static LocalDate renew(LocalDate d,C c){return switch(c){case WEEKLY->d.plusWeeks(1);case MONTHLY->d.plusMonths(1);case QUARTERLY->d.plusMonths(3);case YEARLY->d.plusYears(1);};}static long monthly(long a,C c){return switch(c){case WEEKLY->Math.multiplyExact(a,4);case MONTHLY->a;case QUARTERLY->a/3;case YEARLY->a/12;};}static List<S> due(List<S> ss,LocalDate today,int days){LocalDate until=today.plusDays(days);List<S> out=new ArrayList<>();for(S s:ss)if(s.active&&s.rem&&!s.next.isBefore(today)&&!s.next.isAfter(until))out.add(s);out.sort(Comparator.comparing(S::next));return out;}static String summary(List<S> ss){long t=0;int c=0;for(S s:ss)if(s.active){t=Math.addExact(t,monthly(s.a,s.c));c++;}return c==0?"No active subscriptions yet.":c+" active subscriptions, projected monthly total "+t;}static void eq(String n,Object e,Object a){if(Objects.equals(e,a))p++;else f.add(n+" expected "+e+" got "+a);}public static void main(String[]a){eq("jan31 monthly",LocalDate.of(2024,2,29),renew(LocalDate.of(2024,1,31),C.MONTHLY));eq("weekly",LocalDate.of(2024,3,17),renew(LocalDate.of(2024,3,10),C.WEEKLY));eq("quarterly",LocalDate.of(2024,6,10),renew(LocalDate.of(2024,3,10),C.QUARTERLY));eq("yearly",LocalDate.of(2025,2,28),renew(LocalDate.of(2024,2,29),C.YEARLY));eq("monthly projection",90000L,monthly(90000,C.MONTHLY));eq("yearly projection",10000L,monthly(120000,C.YEARLY));List<S> ss=List.of(new S("Music",90000,C.MONTHLY,LocalDate.of(2024,3,12),true,true),new S("Off",1,C.MONTHLY,LocalDate.of(2024,3,11),true,false),new S("No reminder",1,C.MONTHLY,LocalDate.of(2024,3,11),false,true),new S("Far",1,C.MONTHLY,LocalDate.of(2024,3,30),true,true));eq("due count",1,due(ss,LocalDate.of(2024,3,10),7).size());eq("due first","Music",due(ss,LocalDate.of(2024,3,10),7).get(0).n);eq("summary","3 active subscriptions, projected monthly total 90002",summary(ss));System.out.println("PASSED: "+p+" assertions");if(!f.isEmpty()){f.forEach(System.out::println);System.exit(1);}System.out.println("ALL SUBSCRIPTION CHECKS PASSED");}}
